def overlaps(intervals):
    found = 0
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            a, b = intervals[i], intervals[j]
            if a[0] < b[1] and b[0] < a[1]:
                found += 1
    return found

def main():
    valid = [(0, 10), (20, 30), (40, 50)]
    test = [(0, 10), (5, 15), (40, 50)]
    print(f"valid set overlaps found: {overlaps(valid)}")
    print(f"test set overlaps found: {overlaps(test)}")
    print(f"checker detects planted overlap: {overlaps(test) == 1}")
    print(f"checker passes valid set: {overlaps(valid) == 0}")

main()
